            foreach ($b->coefficients as $j => $right) $result[$i + $j] = $result[$i + $j]->add($left->mul($right));
        }
        return new self($result);
    public function format(string $variable = 'x'): string {
        $result = '';
        for ($i = $this->degree(); $i >= 0; $i--) {
