    for ($i = 0; $i < $count; $i++) { $points[] = $values[2 * $i]; $differences[] = $values[2 * $i + 1]; }
    for ($j = 1; $j < $count; $j++) {
        for ($i = 0; $i < $j; $i++) {
            if ($points[$j]->equals($points[$i])) throw new CommandError('ERROR DUPLICATE X ' . $points[$j]);
        }
